# Assignment lists are baked as [fsa_code, area_pct] pairs; keep only the codes.
FSA_ASSIGN = {k: sorted(x[0] for x in v) for k, v in FSA_ASSIGN.items()}

REGION_SPECS = [
    {"code": "QC-MAURICIE", "name": "Mauricie", "main_city": "Trois-Rivières",
     "marker_latitude": 46.343000, "marker_longitude": -72.544000,
     "display_sequence": 125, "fsas": FSA_ASSIGN["QC-MAURICIE"]},
    {"code": "QC-LANAUDIERE", "name": "Lanaudière", "main_city": "Mascouche",
     "marker_latitude": 45.719468, "marker_longitude": -73.588645,
     "display_sequence": 115, "fsas": FSA_ASSIGN["QC-LANAUDIERE"]},
    {"code": "QC-LAURENTIDES", "name": "Laurentides", "main_city": "Saint-Jérôme",
     "marker_latitude": 45.780000, "marker_longitude": -74.004000,
     "display_sequence": 112, "fsas": FSA_ASSIGN["QC-LAURENTIDES"]},
    {"code": "QC-OUTAOUAIS", "name": "Outaouais", "main_city": "Gatineau",
     "marker_latitude": 45.477000, "marker_longitude": -75.702000,
     "display_sequence": 95, "fsas": FSA_ASSIGN["QC-OUTAOUAIS"]},
]


def main():
    from datetime import datetime

    Region = env["logistics.region"]
    Fsa = env["logistics.fsa"]
    official_ids = tuple(Region.search([("is_official_ltl_region", "=", True)]).ids)
    report = {}

    for spec in REGION_SPECS:
        region = Region.search([("code", "=", spec["code"])], limit=1)
        vals = {
            "code": spec["code"],
            "name": spec["name"],
            "main_city": spec["main_city"],
            "marker_latitude": spec["marker_latitude"],
            "marker_longitude": spec["marker_longitude"],
            "display_sequence": spec["display_sequence"],
            "country_id": COUNTRY_CA.id,
            "state_id": STATE_QC.id,
            "customer_visible": True,
            "is_official_ltl_region": True,
            "active": True,
            "polygon_geojson": json.dumps(POLYGONS[spec["code"]]),
            "boundary_source": BOUNDARY_SOURCE,
            "boundary_source_url": BOUNDARY_URL,
            "boundary_version_date": BOUNDARY_VERSION,
            "boundary_status": "approved",
            "boundary_reviewed_by": APPROVER.id,
            "boundary_reviewed_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "match_priority": 10,
            "coverage_fsa_prefixes": "\n".join(spec["fsas"]),
        }
        if region:
            region.write(vals)
            created = False
        else:
            region = Region.create(vals)
            created = True

        # Geometry metadata through the same authority as the UI action
        is_valid, message, _repaired = RESOLVER.validate_geometry(region.polygon_geojson)
        assert is_valid, f"{spec['code']}: {message}"
        area = RESOLVER.compute_area_km2(region.polygon_geojson)
        checksum = RESOLVER.compute_checksum(region.polygon_geojson)
        region.write({"boundary_area_km2": area, "boundary_checksum": checksum})
        RESOLVER.invalidate_cache(region)
        print(f"REGION {spec['code']}: id={region.id} created={created} "
              f"area_km2={area:,.1f} valid={is_valid}")

        # FSA coverage
        moves = []
        for fsa_code in spec["fsas"]:
            fsa = Fsa.search([("fsa", "=", fsa_code)], limit=1)
            if not fsa:
                print(f"  WARN {fsa_code}: no logistics.fsa record — creating")
                fsa = Fsa.create({
                    "fsa": fsa_code, "province": "QC",
                    "display_city": spec["main_city"], "region_id": region.id,
                    "pickup_supported": True, "delivery_supported": True, "active": True,
                })
                moves.append((fsa_code, "none", "created"))
                continue
            old = fsa.region_id
            if old and old.id in official_ids:
                print(f"  SKIP {fsa_code}: already owned by official {old.code} — not touched")
                continue
            if old and old.id == region.id:
                continue
            old_label = f"{old.code} ({old.name})" if old else "none"
            fsa.write({"region_id": region.id, "active": True})
            if not fsa.display_city:
                fsa.display_city = spec["main_city"]
            moves.append((fsa_code, old_label, region.code))
        for fsa_code, old_label, new_label in moves:
            print(f"  FSA {fsa_code}: {old_label} -> {new_label}")

        report[spec["code"]] = {
            "id": region.id, "created": created,
            "area_km2": round(area, 3), "fsa_count": len(spec["fsas"]),
            "moved_fsas": len(moves),
        }

    print("OVERLAPS (all approved official regions, same province):")
    for o in RESOLVER.detect_overlaps():
        print(f"  {o['region_a'].code} x {o['region_b'].code}: "
              f"{o['overlap_area_km2']} km2 ({o['severity']})")

    env.cr.commit()
    print("RESULT", json.dumps(report))


main()
